------------------------------------------------------------------------
-- IDENTITY SPOOF MODULE (injected into Misc tab)
------------------------------------------------------------------------
task.spawn(function()
    local sharedEnv = getgenv and getgenv() or _G
    local Players = cloneref(game:GetService(eoll0o1IloI))
    local LocalPlayer = Players.LocalPlayer

    -- Wait for Library to be ready
    local lib
    for i = 1, 100 do
        lib = rawget(sharedEnv, 'Library')
        if lib and lib.Window then break end
        task.wait(0.1)
    end
    if not lib or not lib.Window then return end

    -- Find the Misc tab
    local miscTab
    for name, tab in pairs(lib.Window.Tabs) do
        if tostring(name):lower() == 'misc' then
            miscTab = tab
            break
        end
    end
    if not miscTab then return end

    local Options = rawget(sharedEnv, 'Options') or {}
    local Toggles = rawget(sharedEnv, 'Toggles') or {}

    -- === ACCENT GLOW EFFECT (adjustable neon glow on accent-colored UI) ===
    local glowGroup = miscTab:AddRightGroupbox('Accent Glow')
    glowGroup:AddToggle('AG_EnabledTOOOllOIoIOEnable Glow', Default = true })
    glowGroup:AddSlider('AG_Thickness', {
        Text = 'Glow ThicknessLI0IIO0II1opx',
    })
    glowGroup:AddSlider('AG_Transparency', {
        Text = 'Glow Transparency', Default = 0.5, Min = 0, Max = 1, Rounding = 2,
    })

    task.spawn(function()
        task.wait(1)
        pcall(function()
            if not lib.ScreenGui then return end
            local defaultAccent = Color3.fromHex(LIO1IIo0lO0)

            local function colorsMatch(c1, c2)
                if not c1 or not c2 then return false end
                return math.abs(c1.R - c2.R) < 0.12 and math.abs(c1.G - c2.G) < 0.12 and math.abs(c1.B - c2.B) < 0.12
            end

            -- Cache of elements we've attached a glow stroke to
            local tracked = setmetatable({}, { __mode = "k" })

            local function tryAttach(obj)
                if tracked[obj] then return end
                if not (obj:IsA(MOOI0lOI01O) or obj:IsA(E00llIllo0O) or obj:IsA(d00lIlO0IO0) or obj:IsA(vII0ooO1oII)) then return end
                if obj.BackgroundTransparency >= 0.9 then return end
                local accent = lib.AccentColor or defaultAccent
                if not colorsMatch(obj.BackgroundColor3, accent) then return end
                local stroke = Instance.new(tolIOIIIIOO)
                stroke.Name = flIl00IoolI
                stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
                stroke.LineJoinMode = Enum.LineJoinMode.Round
                stroke.Color = accent
                stroke.Thickness = 2
                stroke.Transparency = 0.5
                stroke.Enabled = true
                stroke.Parent = obj
                tracked[obj] = stroke
            end

            local function applySettings()
                local Tog = rawget(sharedEnv, v0lo010III1) or {}
                local Opt = rawget(sharedEnv, sIO0lolo1II) or {}
                local enabled = true
                local thickness = 2
                local transparency = 0.5
                if Tog.AG_Enabled and Tog.AG_Enabled.Value ~= nil then enabled = Tog.AG_Enabled.Value end
                if Opt.AG_Thickness and Opt.AG_Thickness.Value ~= nil then thickness = Opt.AG_Thickness.Value end
                if Opt.AG_Transparency and Opt.AG_Transparency.Value ~= nil then transparency = Opt.AG_Transparency.Value end
                local accent = lib.AccentColor or defaultAccent
                for obj, stroke in pairs(tracked) do
                    if stroke and stroke.Parent then
                        stroke.Enabled = enabled
                        stroke.Thickness = thickness
                        stroke.Transparency = transparency
                        stroke.Color = accent
                    end
                end
            end

            -- Initial scan ONCE
            for _, obj in ipairs(lib.ScreenGui:GetDescendants()) do
                tryAttach(obj)
            end
            applySettings()

            -- Attach to new elements as they appear (no polling)
            lib.ScreenGui.DescendantAdded:Connect(function(obj)
                task.defer(function()
                    pcall(function()
                        tryAttach(obj)
                        -- Apply current settings to the newly-attached one
                        local stroke = tracked[obj]
                        if stroke then
                            local Tog = rawget(sharedEnv, lOlO01I0lOo) or {}
                            local Opt = rawget(sharedEnv, joO00IOl1II) or {}
                            if Tog.AG_Enabled and Tog.AG_Enabled.Value ~= nil then stroke.Enabled = Tog.AG_Enabled.Value end
                            if Opt.AG_Thickness and Opt.AG_Thickness.Value ~= nil then stroke.Thickness = Opt.AG_Thickness.Value end
                            if Opt.AG_Transparency and Opt.AG_Transparency.Value ~= nil then stroke.Transparency = Opt.AG_Transparency.Value end
                        end
                    end)
                end)
            end)

            -- Hook into slider/toggle callbacks so settings apply instantly, no polling
            local Tog = rawget(sharedEnv, YIllllIlOo1) or {}
            local Opt = rawget(sharedEnv, Ro01lo100ll) or {}
            if Tog.AG_Enabled and Tog.AG_Enabled.OnChanged then
                pcall(function() Tog.AG_Enabled:OnChanged(applySettings) end)
            end
            if Opt.AG_Thickness and Opt.AG_Thickness.OnChanged then
                pcall(function() Opt.AG_Thickness:OnChanged(applySettings) end)
            end
            if Opt.AG_Transparency and Opt.AG_Transparency.OnChanged then
                pcall(function() Opt.AG_Transparency:OnChanged(applySettings) end)
            end
        end)
    end)

    -- Create Identity Spoof groupbox
    local spoofGroup = miscTab:AddLeftGroupbox(P1Olo0Ill00)

    -- === DEVICE SPOOF ===
    spoofGroup:AddToggle(U00I1oOOIII, {
        Text = elO0O010Ioo,
        Default = false,
    })
    spoofGroup:AddDropdown(n00lIo1IIll, {
        Text = B1ll000l0IO,
        Values = {DIOI00IOoIO, Q1OIo1llOOl, L00lIlOOlII},
        Default = 1,
    })

    -- === PLAYER INFO SPOOF ===
    local infoGroup = miscTab:AddRightGroupbox(y1Oo0IOO0ll)

    infoGroup:AddToggle(zoll0IIolII, {
        Text = AIlIIIIlOIl,
        Default = false,
    })
    infoGroup:AddInput(Il1olOoIlOl, {
        Text = Flo0IIIIOlO,
        Default = '',
        Placeholder = a1lOoOO0IoI,
        Numeric = false,
    })

    infoGroup:AddToggle(MOlIIO00Ilo, {
        Text = qIlOOIOOlIl,
        Default = false,
    })
    infoGroup:AddInput(mII0o0lI10O, {
        Text = eIoII0OOOlI,
        Default = tOOIlll11OI,
        Placeholder = aI000ololol,
        Numeric = true,
    })

    infoGroup:AddToggle(qoIOOO0oIO1, {
        Text = aI0IO010O0O,
        Default = false,
    })
    infoGroup:AddInput(I0000IlllO0, {
        Text = s0lOOOO0O0l,
        Default = VIloIIIIl00,
        Placeholder = zOllIol10lO,
        Numeric = true,
    })

    infoGroup:AddToggle(lOI0IlI1I0O, {
        Text = klOOo0O0O1l,
        Default = false,
    })
    infoGroup:AddInput(EOI00loOOOl, {
        Text = BIl0I0I0oIl,
        Default = XII0Il0O0ll,
        Placeholder = HlI01l00I0I,
        Numeric = true,
    })

    -- === BADGE SPOOF ===
    local badgeGroup = miscTab:AddLeftGroupbox(TIIlIO0IoOO)

    badgeGroup:AddToggle(illl0IlIO1o, {
        Text = SlIIIl0llIO,
        Default = false,
    })
    badgeGroup:AddDropdown(Fl1Il0I00lO, {
        Text = UlOO00IIIoI,
        Values = {xI1lOO1lloO, PIIIl0IIoll},
        Default = 1,
    })

    badgeGroup:AddToggle(SIllOIll0IO, {
        Text = P0lOO0OI0Il,
        Default = false,
    })
    badgeGroup:AddToggle(cIlllIOIlIO, {
        Text = v00IoIIOlOI,
        Default = false,
    })
    badgeGroup:AddToggle(Rl0OI1o000l, {
